168		}
169		if fin.Success {
170			t.Error("Finished.Success must be false on scanner error")
171		}
172		// Also assert at least one RunError event was emitted before Finished.
173		sawRunError := false
174		for _, ev := range events {
175			if _, ok := ev.(reviewtypes.RunError); ok {
176				sawRunError = true
177				break
178			}
179		}
