	// The returned channel must close when stdout closes. Implementations
	// must emit Started first, Finished{Success: ...} or RunError last,
	// and check scanner.Err() before emitting Finished{Success: true}.
	Parser func(stdout io.Reader) <-chan Event

	// UsePTY routes the agent's stdout through a pseudo-terminal so the
	// child's isatty(STDOUT_FILENO) check returns true. Most CLI tools
	// (libc, Rust, Node) default to block-buffered stdout when not a TTY,
	// which makes their output arrive in one burst at end-of-run instead
