	// diagnostics in Wait() still work. On platforms where pty.Open returns
	// ErrUnsupported (Windows), Start falls back to the regular stdout pipe
	// rather than failing — the streaming benefit is lost but the run
	// completes normally.
	UsePTY bool
}

