// openStdout returns the reader the parser will consume, plus the PTY master
// and slave handles when PTY mode is active (nil otherwise). On platforms
// where pty.Open returns ErrUnsupported (e.g., Windows), it transparently
// falls back to cmd.StdoutPipe so the run still completes — just without
// live streaming.
func (t *ReviewerTemplate) openStdout(cmd *exec.Cmd) (io.Reader, *os.File, *os.File, error) {
	if !t.UsePTY {
		stdout, err := cmd.StdoutPipe()
		if err != nil {
			return nil, nil, nil, fmt.Errorf("pipe: %w", err)
		}
		return stdout, nil, nil, nil
	}
	ptmx, tty, err := pty.Open()
	if err != nil {
		if errors.Is(err, pty.ErrUnsupported) {
			stdout, pipeErr := cmd.StdoutPipe()
			if pipeErr != nil {
				return nil, nil, nil, fmt.Errorf("pipe (pty unsupported): %w", pipeErr)
			}
			return stdout, nil, nil, nil
		}
		return nil, nil, nil, fmt.Errorf("open pty: %w", err)
	}
	// A reasonable winsize keeps width-aware tools from wrapping at 80 cols.
	_ = pty.Setsize(ptmx, &pty.Winsize{Rows: 50, Cols: 200}) //nolint:errcheck // best-effort sizing; failure does not affect streaming
	cmd.Stdout = tty
	// Suppress decoration the agent might now produce because isatty(stdout)
	// is true: colour codes, spinners, in-place updates. The parsers already
	// strip ANSI in some cases (codex) but defending up-front keeps every
	// agent's event stream clean.
	cmd.Env = appendNoDecorationEnv(cmd.Env)
	return &ptyReader{r: ptmx}, ptmx, tty, nil
}

func closePTY(ptmx, tty *os.File) {
	if tty != nil {
		_ = tty.Close() //nolint:errcheck // best-effort cleanup on error path
	}
	if ptmx != nil {
		_ = ptmx.Close() //nolint:errcheck // best-effort cleanup on error path
	}
}

// appendNoDecorationEnv adds env vars that tell the agent not to emit
// terminal decoration even though it now thinks stdout is a TTY.
// Values already set on the parent env are preserved — we only append
// the keys when missing.
func appendNoDecorationEnv(env []string) []string {
	want := map[string]string{
		"NO_COLOR":    "1",
		"FORCE_COLOR": "0",
		"TERM":        "dumb",
	}
	for _, e := range env {
		idx := strings.IndexByte(e, '=')
		if idx < 0 {
			continue
		}
		delete(want, e[:idx])
	}
	for k, v := range want {
		env = append(env, k+"="+v)
	}
	return env
}

// ptyReader translates the Linux ptmx behaviour of returning EIO when the
// child closes its slave side into a normal EOF. macOS already reports EOF
// in that situation; the wrapper makes both platforms look the same to the
// parser's bufio.Scanner.
type ptyReader struct {
	r io.Reader
}

func (p *ptyReader) Read(b []byte) (int, error) {
	n, err := p.r.Read(b)
	if err != nil && isEIO(err) {
		return n, io.EOF
	}
	return n, err //nolint:wrapcheck // passthrough preserves Reader contract
}

func isEIO(err error) bool {
	if errors.Is(err, syscall.EIO) {
		return true
	}
	var pathErr *os.PathError
	if errors.As(err, &pathErr) {
		return errors.Is(pathErr.Err, syscall.EIO)
	}
	return false
}

