1	// Package types — see reviewer.go for package-level rationale.
2	//
3	// template.go provides ReviewerTemplate, a struct that implements
4	// AgentReviewer using two caller-supplied functions: BuildCmd (per-agent
5	// argv/env construction) and Parser (per-agent stdout-to-Event stream).
6	//
7	// All three currently-supported agents (claude-code, codex, gemini-cli)
8	// share the Start/Process/Wait/Events scaffolding. Only the build-cmd
9	// step and the stdout parser genuinely differ. The template owns the
10	// shared lifecycle (spawn → pipe stdout → run parser → forward events
11	// → close on exit); each agent supplies the two unique pieces.
12	package types
13	
14	import (
15		"context"
16		"errors"
17		"fmt"
18		"io"
19		"os"
20		"os/exec"
21		"strings"
22		"syscall"
23	
24		"github.com/creack/pty"
25	)
26	
27	const maxProcessStderrBytes = 64 * 1024
28	
29	// ReviewerTemplate implements AgentReviewer for agents whose only per-agent
30	// quirks are argv/env construction and stdout parsing. Both fields must be
31	// set before Start is called; nil values cause Start to panic immediately.
32	type ReviewerTemplate struct {
33		// AgentName is returned by Name(). Stable identifier per agent.
34		AgentName string
35	
36		// BuildCmd constructs the *exec.Cmd to spawn the agent process,
37		// including argv, stdin (if any), and ENTIRE_REVIEW_* env vars.
38		// The command MUST NOT have started yet; the template will call Start.
39		BuildCmd func(ctx context.Context, cfg RunConfig) *exec.Cmd
40	
41		// Parser converts the agent's stdout stream into a sequence of Events.
42		// The returned channel must close when stdout closes. Implementations
43		// must emit Started first, Finished{Success: ...} or RunError last,
44		// and check scanner.Err() before emitting Finished{Success: true}.
45		Parser func(stdout io.Reader) <-chan Event
46	
47		// UsePTY routes the agent's stdout through a pseudo-terminal so the
48		// child's isatty(STDOUT_FILENO) check returns true. Most CLI tools
49		// (libc, Rust, Node) default to block-buffered stdout when not a TTY,
50		// which makes their output arrive in one burst at end-of-run instead
51		// of streaming as the agent works. PTY mode restores line-buffered
52		// flushing so live progress reaches our parser.
53		//
54		// Stderr remains on a separate pipe regardless, so the bounded-stderr
55		// diagnostics in Wait() still work. On platforms where pty.Open returns
56		// ErrUnsupported (Windows), Start falls back to the regular stdout pipe
57		// rather than failing — the streaming benefit is lost but the run
58		// completes normally.
59		UsePTY bool
60	}
61	
62	// Compile-time check.
63	var _ AgentReviewer = (*ReviewerTemplate)(nil)
64	
65	// Name returns the agent's stable identifier.
66	func (t *ReviewerTemplate) Name() string { return t.AgentName }
67	
68	// Start spawns the agent process, wires stdout through the parser, and
69	// returns a Process whose Events channel streams the parsed event sequence.
70	//
71	// Returns ErrTemplateMisconfigured if AgentName, BuildCmd, or Parser is unset,
72	// or if BuildCmd returns nil. These are programmer errors but failing fast
73	// with a typed error is friendlier than a downstream nil deref — and it
74	// keeps Start from panicking inside a multi-agent fan-out (CU8) where one
75	// misconfigured template would otherwise kill the whole run.
76	func (t *ReviewerTemplate) Start(ctx context.Context, cfg RunConfig) (Process, error) {
77		if t.AgentName == "" {
78			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (empty AgentName)", ErrTemplateMisconfigured)
79		}
80		if t.BuildCmd == nil {
81			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil BuildCmd for agent %q)", ErrTemplateMisconfigured, t.AgentName)
82		}
83		if t.Parser == nil {
84			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil Parser for agent %q)", ErrTemplateMisconfigured, t.AgentName)
85		}
86		cmd := t.BuildCmd(ctx, cfg)
87		if cmd == nil {
88			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (BuildCmd returned nil for agent %q)", ErrTemplateMisconfigured, t.AgentName)
89		}
90		stdout, ptmx, ttySlave, err := t.openStdout(cmd)
91		if err != nil {
92			return nil, fmt.Errorf("%s: stdout: %w", t.AgentName, err)
93		}
94		stderr, err := cmd.StderrPipe()
95		if err != nil {
96			closePTY(ptmx, ttySlave)
97			return nil, fmt.Errorf("%s: stderr pipe: %w", t.AgentName, err)
98		}
99		if err := cmd.Start(); err != nil {
100			closePTY(ptmx, ttySlave)
101			return nil, fmt.Errorf("%s: start: %w", t.AgentName, err)
102		}
103		// In PTY mode the parent's copy of the slave fd is no longer needed —
104		// the child has already dup'd it during fork/exec, so closing here lets
105		// the master see EOF/EIO when the child eventually closes its side.
106		if ttySlave != nil {
107			_ = ttySlave.Close()
108		}
109		p := &templateProcess{
110			ctx:        ctx,
111			agentName:  t.AgentName,
112			cmd:        cmd,
113			events:     make(chan Event, 32),
114			stderr:     &boundedStderrBuffer{limit: maxProcessStderrBytes},
115			stderrDone: make(chan struct{}),
116			ptmx:       ptmx,
117		}
118		go p.run(stdout, t.Parser)
119		go p.captureStderr(stderr)
120		return p, nil
121	}
122	
123	// openStdout returns the reader the parser will consume, plus the PTY master
124	// and slave handles when PTY mode is active (nil otherwise). On platforms
125	// where pty.Open returns ErrUnsupported (e.g., Windows), it transparently
126	// falls back to cmd.StdoutPipe so the run still completes — just without
127	// live streaming.
128	func (t *ReviewerTemplate) openStdout(cmd *exec.Cmd) (io.Reader, *os.File, *os.File, error) {
129		if !t.UsePTY {
130			stdout, err := cmd.StdoutPipe()
131			if err != nil {
132				return nil, nil, nil, fmt.Errorf("pipe: %w", err)
133			}
134			return stdout, nil, nil, nil
135		}
136		ptmx, tty, err := pty.Open()
137		if err != nil {
138			if errors.Is(err, pty.ErrUnsupported) {
139				stdout, pipeErr := cmd.StdoutPipe()
140				if pipeErr != nil {
141					return nil, nil, nil, fmt.Errorf("pipe (pty unsupported): %w", pipeErr)
142				}
143				return stdout, nil, nil, nil
144			}
145			return nil, nil, nil, fmt.Errorf("open pty: %w", err)
146		}
147		// A reasonable winsize keeps width-aware tools from wrapping at 80 cols.
148		_ = pty.Setsize(ptmx, &pty.Winsize{Rows: 50, Cols: 200}) //nolint:errcheck // best-effort sizing; failure does not affect streaming
149		cmd.Stdout = tty
150		// Suppress decoration the agent might now produce because isatty(stdout)
151		// is true: colour codes, spinners, in-place updates. The parsers already
152		// strip ANSI in some cases (codex) but defending up-front keeps every
153		// agent's event stream clean.
154		cmd.Env = appendNoDecorationEnv(cmd.Env)
155		return &ptyReader{r: ptmx}, ptmx, tty, nil
156	}
157	
158	func closePTY(ptmx, tty *os.File) {
159		if tty != nil {
160			_ = tty.Close()
161		}
162		if ptmx != nil {
163			_ = ptmx.Close()
164		}
165	}
166	
167	// appendNoDecorationEnv adds env vars that tell the agent not to emit
168	// terminal decoration even though it now thinks stdout is a TTY.
169	// Values already set on the parent env are preserved — we only append
170	// the keys when missing.
171	func appendNoDecorationEnv(env []string) []string {
172		want := map[string]string{
173			"NO_COLOR":    "1",
174			"FORCE_COLOR": "0",
175			"TERM":        "dumb",
176		}
177		for _, e := range env {
178			idx := strings.IndexByte(e, '=')
179			if idx < 0 {
180				continue
181			}
182			delete(want, e[:idx])
183		}
184		for k, v := range want {
185			env = append(env, k+"="+v)
186		}
187		return env
188	}
189	
190	// ptyReader translates the Linux ptmx behaviour of returning EIO when the
191	// child closes its slave side into a normal EOF. macOS already reports EOF
192	// in that situation; the wrapper makes both platforms look the same to the
193	// parser's bufio.Scanner.
194	type ptyReader struct {
195		r io.Reader
196	}
197	
198	func (p *ptyReader) Read(b []byte) (int, error) {
199		n, err := p.r.Read(b)
200		if err != nil && isEIO(err) {
201			return n, io.EOF
202		}
203		return n, err //nolint:wrapcheck // passthrough preserves Reader contract
204	}
205	
206	func isEIO(err error) bool {
207		if errors.Is(err, syscall.EIO) {
208			return true
209		}
210		var pathErr *os.PathError
211		if errors.As(err, &pathErr) {
212			return errors.Is(pathErr.Err, syscall.EIO)
213		}
214		return false
215	}
216	
217	// ErrTemplateMisconfigured is returned by ReviewerTemplate.Start when one of
218	// the required fields (AgentName, BuildCmd, Parser) is unset, or when
219	// BuildCmd returns nil. Use errors.Is to detect this in tests or higher
220	// layers (e.g., a multi-agent orchestrator that needs to skip a misconfigured
221	// agent rather than crashing the whole run).
222	var ErrTemplateMisconfigured = errors.New("ReviewerTemplate misconfigured")
223	
224	// templateProcess is the shared Process implementation for ReviewerTemplate.
225	type templateProcess struct {
226		ctx        context.Context
227		agentName  string
228		cmd        *exec.Cmd
229		events     chan Event
230		stderr     *boundedStderrBuffer
231		stderrDone chan struct{}
232		// ptmx is the PTY master when UsePTY=true, nil otherwise. The parser
233		// goroutine in run() closes it once the parser's event channel drains —
234		// closing earlier would interrupt streaming, closing later would leak
235		// the fd if the consumer ignores Wait.
236		ptmx *os.File
237	}
238	
239	// Events returns the channel that streams parsed events from the agent process.
240	func (p *templateProcess) Events() <-chan Event { return p.events }
241	
242	// Wait returns the agent process's exit error with bounded stderr diagnostics.
243	//
244	// Per CU2's Process contract: nil on clean exit (exit code 0); ctx.Err()
245	// on cancellation; ProcessError wrapping *exec.ExitError on non-zero exit
246	// with stderr; other types for I/O or pipe failures. ProcessError implements
247	// Unwrap so callers can use errors.As and errors.Is to classify.
248	func (p *templateProcess) Wait() error {
249		if p.stderrDone != nil {
250			<-p.stderrDone
251		}
252		err := p.cmd.Wait()
253		if err != nil && p.ctx.Err() != nil {
254			return p.ctx.Err() //nolint:wrapcheck // preserve Process cancellation contract
255		}
256		if err != nil {
257			if stderr := p.stderr.String(); stderr != "" {
258				return &ProcessError{AgentName: p.agentName, Err: err, Stderr: stderr}
259			}
260		}
261		return err //nolint:wrapcheck // interface boundary; classifyStatus needs raw type
262	}
263	
264	func (p *templateProcess) run(stdout io.Reader, parser func(io.Reader) <-chan Event) {
265		defer close(p.events)
266		if p.ptmx != nil {
267			defer func() { _ = p.ptmx.Close() }()
268		}
269		for ev := range parser(stdout) {
270			p.events <- ev
271		}
272	}
273	
274	func (p *templateProcess) captureStderr(stderr io.Reader) {
275		defer close(p.stderrDone)
276		_, _ = io.Copy(p.stderr, stderr) //nolint:errcheck // stderr is best-effort diagnostic context
277	}
278	
279	// ProcessError wraps a process failure with bounded stderr diagnostics.
280	// Unwrap preserves the underlying error, so callers can still use errors.As
281	// for *exec.ExitError or errors.Is for lower-level sentinels.
282	type ProcessError struct {
283		AgentName string
284		Err       error
285		Stderr    string
286	}
287	
288	func (e *ProcessError) Error() string {
289		if e.Stderr == "" {
290			return fmt.Sprintf("%s: %v", e.AgentName, e.Err)
291		}
292		return fmt.Sprintf("%s: %v: stderr: %s", e.AgentName, e.Err, e.Stderr)
293	}
294	
295	func (e *ProcessError) Unwrap() error { return e.Err }
296	
297	type boundedStderrBuffer struct {
298		limit     int
299		buf       []byte
300		truncated bool
