			if err := s.Err(); err != nil {
				ch <- RunError{Err: err}
				ch <- Finished{Success: false}
				return
			}
			ch <- Finished{Success: true}
		}()
		return ch
	}

	tmpl := &ReviewerTemplate{
		AgentName: "pty-test",
		BuildCmd: func(ctx context.Context, _ RunConfig) *exec.Cmd {
			// Three short lines, flushed individually so PTY mode is the
			// only way they arrive before exit on stdio-buffering platforms.
			return exec.CommandContext(ctx, "sh", "-c", "printf 'a\\n'; printf 'b\\n'; printf 'c\\n'")
		},
		Parser: lineParser,
		UsePTY: true,
	}

	proc, err := tmpl.Start(context.Background(), RunConfig{})
	if err != nil {
		t.Fatalf("Start() error: %v", err)
	}

	var got []Event
	timeout := time.After(5 * time.Second)
	for {
		select {
		case ev, ok := <-proc.Events():
			if !ok {
				goto done
			}
			got = append(got, ev)
		case <-timeout:
			t.Fatalf("timed out collecting events (got %d so far)", len(got))
		}
	}
done:
	if err := proc.Wait(); err != nil {
		t.Fatalf("Wait() error: %v", err)
	}

	// Expect: Started, AssistantText{a}, AssistantText{b}, AssistantText{c}, Finished{true}.
	if len(got) != 5 {
		t.Fatalf("got %d events, want 5: %v", len(got), got)
	}
	if _, ok := got[0].(Started); !ok {
		t.Errorf("events[0] = %T, want Started", got[0])
	}
	for i, want := range []string{"a", "b", "c"} {
		at, ok := got[i+1].(AssistantText)
		if !ok {
			t.Errorf("events[%d] = %T, want AssistantText", i+1, got[i+1])
			continue
		}
		if at.Text != want {
			t.Errorf("events[%d].Text = %q, want %q", i+1, at.Text, want)
		}
	}
	fin, ok := got[4].(Finished)
	if !ok {
		t.Fatalf("events[4] = %T, want Finished", got[4])
	}
	if !fin.Success {
		t.Error("Finished.Success = false, want true")
	}
}

// TestReviewerTemplate_UsePTYAppendsNoDecorationEnv pins that PTY mode
// sets NO_COLOR/FORCE_COLOR/TERM=dumb on the child env to suppress
// terminal decoration the agent might emit now that isatty(stdout) is true.
// The test sniffs the child's env via /usr/bin/env to avoid relying on
// shell built-in behaviour.
func TestReviewerTemplate_UsePTYAppendsNoDecorationEnv(t *testing.T) {
	skipOnWindows(t, "PTY unsupported on Windows")
	t.Parallel()

	lineParser := func(r io.Reader) <-chan Event {
		ch := make(chan Event, 16)
		go func() {
			defer close(ch)
			ch <- Started{}
			s := bufio.NewScanner(r)
			for s.Scan() {
				ch <- AssistantText{Text: strings.TrimRight(s.Text(), "\r")}
			}
			ch <- Finished{Success: true}
		}()
		return ch
	}

	tmpl := &ReviewerTemplate{
		AgentName: "pty-env-test",
		BuildCmd: func(ctx context.Context, _ RunConfig) *exec.Cmd {
			c := exec.CommandContext(ctx, "sh", "-c", "echo NO_COLOR=$NO_COLOR; echo TERM=$TERM; echo FORCE_COLOR=$FORCE_COLOR")
			c.Env = []string{"PATH=/usr/bin:/bin"} // start minimal so appended vars are detectable
			return c
		},
		Parser: lineParser,
		UsePTY: true,
	}

	proc, err := tmpl.Start(context.Background(), RunConfig{})
	if err != nil {
		t.Fatalf("Start() error: %v", err)
	}

	var combined strings.Builder
	for ev := range proc.Events() {
		if at, ok := ev.(AssistantText); ok {
			combined.WriteString(at.Text)
			combined.WriteString("\n")
		}
	}
	_ = proc.Wait() //nolint:errcheck // status irrelevant; we only inspect output

	out := combined.String()
	for _, want := range []string{"NO_COLOR=1", "TERM=dumb", "FORCE_COLOR=0"} {
		if !strings.Contains(out, want) {
			t.Errorf("PTY mode did not export %s; output was:\n%s", want, out)
		}
	}
}

