// streaming-smoke is a self-contained verifier for the line-by-line
// streaming contract that `entire review` depends on. It does NOT call any
// agent API.
//
// What it proves
//
// The review pipeline parses agent stdout with bufio.Scanner and emits one
// AssistantText event per line as soon as the line arrives at the pipe's
// read end. To verify the whole template → parser → channel path is
// truly streaming (rather than batching at end of run), this binary spawns
// itself in "probe" mode through ReviewerTemplate and prints the timestamp
// each event arrives at.
//
// Usage:
//
//	go run ./e2e/streaming-smoke
//
// Expected output (timestamps approximate):
//
//	=== streaming-smoke ===
//	  +    0ms  Started{}
//	  +    1ms  AssistantText  "probe line 1/5"
//	  +  150ms  AssistantText  "probe line 2/5"
//	  +  301ms  AssistantText  "probe line 3/5"
//	  +  452ms  AssistantText  "probe line 4/5"
//	  +  603ms  AssistantText  "probe line 5/5"
//	  +  604ms  Finished{Success:true}
//
// The five AssistantText events should stagger by ~150ms — the probe's
// sleep between writes. If they all arrive together at the end, something
// upstream of the parser is batching.
package main

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"time"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

const probeFlag = "--probe"

func main() {
	// Self-spawn pattern: re-exec the same binary with --probe to act as
	// the fake "streaming agent". Lets the whole smoke test live in one
	// file the user can run with `go run ./e2e/streaming-smoke`.
	if len(os.Args) > 1 && os.Args[1] == probeFlag {
		runProbe()
		return
	}
	if err := runHarness(); err != nil {
		fmt.Fprintln(os.Stderr, "streaming-smoke:", err)
		os.Exit(1)
	}
}

// runProbe is the fake-agent side. It writes five newline-terminated lines
// with 150ms between each and flushes per line by calling fmt.Fprintln
// (which does an unbuffered write to os.Stdout). That's how a well-behaved
// streaming CLI emits output to a pipe.
func runProbe() {
	const lineCount = 5
	const between = 150 * time.Millisecond
	for i := 1; i <= lineCount; i++ {
		fmt.Fprintf(os.Stdout, "probe line %d/%d\n", i, lineCount)
		time.Sleep(between)
	}
}

func runHarness() error {
	self, err := os.Executable()
	if err != nil {
		return fmt.Errorf("locate self: %w", err)
	}

	tmpl := &reviewtypes.ReviewerTemplate{
		AgentName: "smoke-probe",
		BuildCmd: func(ctx context.Context, _ reviewtypes.RunConfig) *exec.Cmd {
			return exec.CommandContext(ctx, self, probeFlag)
		},
		Parser: lineParser,
	}

	started := time.Now()
	proc, err := tmpl.Start(context.Background(), reviewtypes.RunConfig{})
	if err != nil {
		return fmt.Errorf("start: %w", err)
	}

	fmt.Println("=== streaming-smoke ===")
	for ev := range proc.Events() {
		printEvent(time.Since(started), ev)
	}
	if err := proc.Wait(); err != nil {
		return fmt.Errorf("wait: %w", err)
	}
	return nil
}

func printEvent(elapsed time.Duration, ev reviewtypes.Event) {
	prefix := fmt.Sprintf("  + %4dms  ", elapsed.Milliseconds())
	switch e := ev.(type) {
	case reviewtypes.AssistantText:
		fmt.Printf("%sAssistantText  %q\n", prefix, e.Text)
	case reviewtypes.Started:
		fmt.Printf("%sStarted{}\n", prefix)
	case reviewtypes.Finished:
		fmt.Printf("%sFinished{Success:%v}\n", prefix, e.Success)
	default:
		fmt.Printf("%s%T\n", prefix, ev)
	}
}

func lineParser(r io.Reader) <-chan reviewtypes.Event {
	ch := make(chan reviewtypes.Event, 16)
	go func() {
		defer close(ch)
		ch <- reviewtypes.Started{}
		s := bufio.NewScanner(r)
		for s.Scan() {
			line := strings.TrimRight(s.Text(), "\r")
			if line == "" {
				continue
			}
			ch <- reviewtypes.AssistantText{Text: line}
		}
		if err := s.Err(); err != nil {
			ch <- reviewtypes.RunError{Err: err}
			ch <- reviewtypes.Finished{Success: false}
			return
		}
		ch <- reviewtypes.Finished{Success: true}
	}()
	return ch
}

