package claudecode

import (
    "bufio"
    "context"
    "encoding/json"
    "fmt"
    "io"
    "os"
    "os/exec"

    "github.com/entireio/cli/cmd/entire/cli/review"
    reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// parseClaudeOutput converts claude's --output-format stream-json --verbose
// stdout into a stream of Events. Each stdout line is one JSON envelope:
//   - {"type":"system",...}      session metadata, hooks; swallowed
//   - {"type":"assistant",...}   one content block at a time; text → AssistantText,
//                                tool_use → ToolCall, thinking → swallowed
//   - {"type":"user",...}        tool_result echoes; swallowed
//   - {"type":"result",...}      final summary; emits Tokens then Finished
//
// Emits Started first, Finished{Success:...} last (success follows result.is_error).
// On a scanner error (torn stream), emits RunError then Finished{Success:false}.
//
// Exposed for golden-file contract testing.
func parseClaudeOutput(r io.Reader) <-chan reviewtypes.Event {
    out := make(chan reviewtypes.Event, 32)
    go func() {
        defer close(out)
        out <- reviewtypes.Started{}
        scanner := bufio.NewScanner(r)
        // Stream-json messages can carry full tool-input payloads; size headroom.
        scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
        var finalResult *claudeResultEnvelope
        for scanner.Scan() {
            line := scanner.Bytes()
            if len(line) == 0 {
                continue
            }
            var env claudeEnvelope
            if err := json.Unmarshal(line, &env); err != nil {
                // Garbled line: surface as RunError but keep parsing — one bad
                // line should not tear the whole stream.
                out <- reviewtypes.RunError{Err: fmt.Errorf("claude stream-json: %w", err)}
                continue
            }
            switch env.Type {
            case "assistant":
                for _, block := range env.Message.Content {
                    switch block.Type {
                    case "text":
                        if block.Text != "" {
                            out <- reviewtypes.AssistantText{Text: block.Text}
                        }
                    case "tool_use":
                        args, _ := json.Marshal(block.Input) //nolint:errcheck
                        out <- reviewtypes.ToolCall{Name: block.Name, Args: string(args)}
                    // "thinking" intentionally swallowed.
                    }
                }
            case "result":
                cp := env
                finalResult = &claudeResultEnvelope{
                    IsError: env.IsError,
                    Usage:   env.Usage,
                }
                _ = cp
            // "system", "user", "rate_limit_event" swallowed.
            }
        }
        if err := scanner.Err(); err != nil {
            out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
            out <- reviewtypes.Finished{Success: false}
            return
        }
        if finalResult != nil {
            in := finalResult.Usage.InputTokens + finalResult.Usage.CacheReadInputTokens + finalResult.Usage.CacheCreationInputTokens
            out <- reviewtypes.Tokens{In: in, Out: finalResult.Usage.OutputTokens}
            out <- reviewtypes.Finished{Success: !finalResult.IsError}
            return
        }
        // No result envelope arrived — treat as torn stream.
        out <- reviewtypes.Finished{Success: false}
    }()
    return out
}

// Envelope types. Fields kept minimal — anything we don't need stays
// untyped (omitted from the struct) and the json decoder ignores it.
type claudeEnvelope struct {
    Type    string          `json:"type"`
    Message claudeMessage   `json:"message"`
    IsError bool            `json:"is_error"`
    Usage   claudeUsage     `json:"usage"`
}

type claudeMessage struct {
    Content []claudeBlock `json:"content"`
}

type claudeBlock struct {
    Type  string          `json:"type"`
    Text  string          `json:"text"`
    Name  string          `json:"name"`
    Input json.RawMessage `json:"input"`
}

type claudeUsage struct {
    InputTokens              int `json:"input_tokens"`
    OutputTokens             int `json:"output_tokens"`
    CacheReadInputTokens     int `json:"cache_read_input_tokens"`
    CacheCreationInputTokens int `json:"cache_creation_input_tokens"`
}

type claudeResultEnvelope struct {
    IsError bool
    Usage   claudeUsage
}
```

